class UserOut(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    active: Annotated[bool, Field(title='Active')]
    auth_provider: Annotated[
        str,
        Field(
            alias='authProvider',
            description='`local` or `oidc:<provider>`.',
            title='Authprovider',
        ),
    ]
    created_at: Annotated[AwareDatetime, Field(alias='createdAt', title='Createdat')]
    display_name: Annotated[str, Field(alias='displayName', title='Displayname')]
    email: Annotated[str | None, Field(title='Email')]
    external_roles: Annotated[
        list[str],
        Field(
            alias='externalRoles',
            description='Roles of the identity provider seen at the last sign-in.',
            title='Externalroles',
        ),
    ]
    id: Annotated[UUID, Field(title='Id')]
    last_login_at: Annotated[
        AwareDatetime | None, Field(alias='lastLoginAt', title='Lastloginat')
    ]
    locale: Annotated[str | None, Field(title='Locale')]
    locked: Annotated[
        bool,
        Field(
            description='Whether sign-in is blocked after failed attempts.',
            title='Locked',
        ),
    ]
    member_id: Annotated[UUID | None, Field(alias='memberId', title='Memberid')]
    member_name: Annotated[str | None, Field(alias='memberName', title='Membername')]
    must_change_password: Annotated[
        bool, Field(alias='mustChangePassword', title='Mustchangepassword')
    ]
    roles: Annotated[list[UserRoleOut], Field(title='Roles')]
    updated_at: Annotated[AwareDatetime, Field(alias='updatedAt', title='Updatedat')]
    username: Annotated[str, Field(title='Username')]
    version: Annotated[
        int,
        Field(
            description='Optimistic-lock version; send it back in If-Match.',
            title='Version',
        ),
    ]


class PageUserOut(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    items: Annotated[list[UserOut], Field(title='Items')]
    total: Annotated[
        int,
        Field(
            description='Number of rows that match the filters, across all pages.',
            title='Total',
        ),
    ]


class PlanningOut(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    can_assign: Annotated[
        bool,
        Field(
            alias='canAssign',
            description='The caller may create assignments at all.',
            title='Canassign',
        ),
    ]
    skills: Annotated[
        list[SkillRef],
        Field(description='Every skill the response refers to.', title='Skills'),
    ]
    start: Annotated[
        date_aliased, Field(description='Monday of the first week.', title='Start')
    ]
    tasks: Annotated[list[PoolTask], Field(title='Tasks')]
    teams: Annotated[list[TeamPlan], Field(title='Teams')]
    weeks: Annotated[list[WeekOut], Field(title='Weeks')]
